// generated by gemini-3.5-flash-lite for PR #5979 (round 0): bson_roundtrip_equality
// intent: Verify that serialization via single-pass BSON can be correctly parsed back and matches original JSON.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::json j = {{"hello", "world"}, {"number", 123}, {"arr", {1, 2, 3}}};
        auto v = nlohmann::json::to_bson(j);
        nlohmann::json j2 = nlohmann::json::from_bson(v);
        std::cout << "match: " << (j == j2 ? "true" : "false") << "\n";
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << "\n";
    }
}
